import numpy as np
import time


def exact_score(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0:
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    # pad with zeros at both ends
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    # ||f*f||_2^2 = sum_j (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3
    a = Lp[:-1]
    b = Lp[1:]
    norm2sq = np.sum(a * a + a * b + b * b) / 3.0
    norm1 = s * s
    norminf = Lp.max()
    if norminf <= 0:
        return -1.0
    return norm2sq / (norm1 * norminf)


def make_h(N, a1, a2, a3):
    i = np.arange(N) + 0.5
    x = 2.0 * np.pi * i / N
    h = 1.0 + a1 * np.cos(x) + a2 * np.cos(2.0 * x) + a3 * np.cos(3.0 * x)
    return np.maximum(h, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 512

    best_h = None
    best_r = -1.0
    best_coef = (0.0, 0.0, 0.0)

    # Coarse grid
    a1_vals = np.arange(-1.0, 1.0 + 1e-9, 0.25)
    a2_vals = np.arange(-0.5, 0.5 + 1e-9, 0.25)
    a3_vals = np.array([-0.25, 0.0, 0.25])

    for a1 in a1_vals:
        for a2 in a2_vals:
            for a3 in a3_vals:
                h = make_h(N, a1, a2, a3)
                r = exact_score(h)
                if r > best_r:
                    best_r = r
                    best_h = h
                    best_coef = (a1, a2, a3)
                if time.process_time() - t0 > 0.5 * budget_seconds:
                    break
            if time.process_time() - t0 > 0.5 * budget_seconds:
                break
        if time.process_time() - t0 > 0.5 * budget_seconds:
            break

    # Also consider the start if it scores better
    if start is not None:
        s = np.asarray(start, dtype=float)
        rs = exact_score(s)
        if rs > best_r:
            best_r = rs
            best_h = s.copy()

    # Coordinate refinement
    coef = list(best_coef)
    step = 0.1
    deadline = 0.9 * budget_seconds
    while step >= 1e-3:
        improved = True
        while improved:
            improved = False
            for k in range(3):
                for sign in (1.0, -1.0):
                    if time.process_time() - t0 > deadline:
                        break
                    trial = coef.copy()
                    trial[k] += sign * step
                    h = make_h(N, *trial)
                    r = exact_score(h)
                    if r > best_r:
                        best_r = r
                        best_h = h
                        coef = trial
                        improved = True
                if time.process_time() - t0 > deadline:
                    break
            if time.process_time() - t0 > deadline:
                break
        if time.process_time() - t0 > deadline:
            break
        step *= 0.5

    if best_h is None:
        best_h = np.ones(50)
    return np.asarray(best_h, dtype=float)

import numpy as np
import time


def score(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0
    return q / (s * s * m)


def score_p(h, p):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0
    scaled = Lp / m
    Mp = m * (np.mean(scaled ** p)) ** (1.0 / p)
    if Mp <= 0:
        return 0.0
    return q / (s * s * Mp)


def resample(h, n):
    if h.size == n:
        return h.copy()
    idx = np.linspace(0, h.size - 1, n)
    return np.interp(idx, np.arange(h.size), h)


def _golden(fn, lo, hi, iters=18):
    """Golden-section maximization of fn on [lo, hi]."""
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    a, b = lo, hi
    c = b - gr * (b - a)
    d = a + gr * (b - a)
    fc = fn(c)
    fd = fn(d)
    for _ in range(iters):
        if fc > fd:
            b, d, fd = d, c, fc
            c = b - gr * (b - a)
            fc = fn(c)
        else:
            a, c, fc = c, d, fd
            d = a + gr * (b - a)
            fd = fn(d)
    return (a + b) * 0.5


def _coord_sweep(h, fn, deadline, hi_factor=3.0, max_iters=18):
    """One cyclic coordinate-descent sweep over all indices. Returns (h, improved)."""
    n = h.size
    improved = False
    order = np.arange(n)
    for i in order:
        if time.process_time() >= deadline:
            break
        cur_max = h.max()
        hi = max(hi_factor * cur_max, h[i] * 2.0 + 1e-9)
        lo = 0.0
        old = h[i]

        def f(x, i=i):
            h[i] = x
            return fn(h)

        # coarse bracket: test a few points, then golden refine
        try:
            xs = np.linspace(lo, hi, 7)
            vals = [f(x) for x in xs]
            k = int(np.argmax(vals))
            if k == 0:
                a, b = xs[0], xs[1]
            elif k == len(xs) - 1:
                a, b = xs[-2], xs[-1]
            else:
                a, b = xs[k - 1], xs[k + 1]
            xbest = _golden(f, a, b, iters=max_iters)
            vbest = f(xbest)
            vold = f(old)
            if vbest > vold:
                h[i] = xbest
                improved = True
            else:
                h[i] = old
        except Exception:
            h[i] = old
    return h, improved


def _pair_sweep(h, fn, deadline, hi_factor=2.0):
    """Pairwise (i,i+1) coordinate moves: scale both by a common factor."""
    n = h.size
    improved = False
    for i in range(n - 1):
        if time.process_time() >= deadline:
            break
        a0 = h[i]
        b0 = h[i + 1]
        if a0 + b0 <= 0:
            continue

        def f(t, i=i, a0=a0, b0=b0):
            # t in [0,1] blends toward (avg,avg); also allow scaling
            h[i] = a0 * (1 - t) + t * (a0 + b0) * 0.5
            h[i + 1] = b0 * (1 - t) + t * (a0 + b0) * 0.5
            return fn(h)

        try:
            v0 = f(0.0)
            v1 = f(1.0)
            if v1 > v0:
                h[i] = (a0 + b0) * 0.5
                h[i + 1] = (a0 + b0) * 0.5
                improved = True
            else:
                h[i] = a0
                h[i + 1] = b0
        except Exception:
            h[i] = a0
            h[i + 1] = b0
    return h, improved


def _coord_descent(base, deadline, ps=(256, 1024, 4096, 16384, None)):
    best = np.asarray(base, dtype=float).copy()
    best = np.clip(best, 0, None)
    best_score = score(best)
    if best.sum() <= 0:
        return best, best_score

    nps = len(ps)
    for pi, p in enumerate(ps):
        if time.process_time() >= deadline:
            break
        rem = deadline - time.process_time()
        phase_end = time.process_time() + rem / max(1, (nps - pi))
        if phase_end > deadline:
            phase_end = deadline
        if p is None:
            fn = score
        else:
            fn = (lambda h, p=p: score_p(h, p))

        cur = best.copy()
        cur_score = fn(cur)
        for sweep in range(50):
            if time.process_time() >= phase_end:
                break
            cur, imp = _coord_sweep(cur, fn, phase_end)
            # try pair moves occasionally
            if sweep % 2 == 1 and time.process_time() < phase_end:
                cur, imp2 = _pair_sweep(cur, fn, phase_end)
                imp = imp or imp2
            tr = score(cur)
            if tr > best_score:
                best = cur.copy()
                best_score = tr
            if not imp:
                break
    return best, best_score


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    best = base.copy()
    best_score = score(best)

    # Main: deterministic coordinate descent through p-ladder
    best, best_score = _coord_descent(best, deadline)

    # Final true-R coordinate pass if time remains
    if time.process_time() < deadline:
        cur = best.copy()
        for _ in range(20):
            if time.process_time() >= deadline:
                break
            cur, imp = _coord_sweep(cur, score, deadline)
            tr = score(cur)
            if tr > best_score:
                best = cur.copy()
                best_score = tr
            if not imp:
                break

    best = np.clip(np.asarray(best, dtype=float), 0, None)
    if best.sum() <= 0:
        best = np.ones(50)
    return best

