def _window_sweep(h, fn, deadline, sizes=(3, 5, 9, 17)):
    """Slide a window of given size; blend window toward its mean by t in [0,1]."""
    n = h.size
    improved = False
    for w in sizes:
        if w > n:
            continue
        for start in range(0, n - w + 1):
            if time.process_time() >= deadline:
                return h, improved
            seg = h[start:start + w].copy()
            mu = seg.mean()

            def f(t, start=start, seg=seg, mu=mu, w=w):
                h[start:start + w] = seg * (1 - t) + t * mu
                return fn(h)

            try:
                v0 = f(0.0)
                v1 = f(1.0)
                if v1 > v0:
                    h[start:start + w] = mu
                    improved = True
                else:
                    h[start:start + w] = seg
            except Exception:
                h[start:start + w] = seg
    return h, improved


