def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90
    phaseA_end = t0 + budget_seconds * 0.45
    phaseB_end = t0 + budget_seconds * 0.80

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(78)
    else:
        base = np.ones(78)

    best = base.copy()
    best_score = score(best)

    # Phase A: full descent on start shape
    a_best, a_score = _deterministic_descent(
        base, min(phaseA_end, deadline),
        [256, 1024, 4096, 16384, 65536, None])
    if a_score > best_score:
        best, best_score = a_best, a_score

    # Phase B: resample to N=136 and N=104, run shorter descent
    if time.process_time() < phaseB_end:
        for n_new in (136, 104):
            if time.process_time() >= phaseB_end:
                break
            cand = resample(best, n_new)
            rem = phaseB_end - time.process_time()
            sub_end = time.process_time() + rem / 2.0
            if sub_end > phaseB_end:
                sub_end = phaseB_end
            c_best, c_score = _deterministic_descent(
                cand, sub_end, [1024, 8192, None])
            if c_score > best_score:
                best, best_score = c_best, c_score

    # Phase C: true-score polish
    if time.process_time() < deadline:
        cur = best.copy()
        for _ in range(20):
            if time.process_time() >= deadline:
                break
            cur, imp1 = _coord_sweep(cur, score, deadline)
            if time.process_time() >= deadline:
                break
            cur, imp2 = _window_sweep(cur, score, deadline)
            tr = score(cur)
            if tr > best_score:
                best = cur.copy()
                best_score = tr
            if not (imp1 or imp2):
                break

    best = np.clip(np.asarray(best, dtype=float), 0, None)
    if best.sum() <= 0:
        best = np.ones(78)
    return best

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    return Lp


def score(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    Lp = _knots(h)
    a = Lp[:-1]
    b = Lp[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0
    return q / (s * s * m)


def score_p(h, p):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    Lp = _knots(h)
    a = Lp[:-1]
    b = Lp[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0
    scaled = Lp / m
    Mp = m * (np.mean(scaled ** p)) ** (1.0 / p)
    if Mp <= 0:
        return 0.0
    return q / (s * s * Mp)


def score_and_grad_p(h, p):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0, np.zeros(n)
    scaled = Lp / m
    sp = scaled ** p
    mean_sp = np.mean(sp)
    if mean_sp <= 0:
        return 0.0, np.zeros(n)
    Mp = m * mean_sp ** (1.0 / p)
    if Mp <= 0:
        return 0.0, np.zeros(n)
    Sp = q / (s * s * Mp)

    dq = np.zeros(Lp.size)
    dq += (2.0 * Lp) / 3.0
    dq[:-1] += Lp[1:] / 3.0
    dq[1:] += Lp[:-1] / 3.0

    N = Lp.size
    dMp = (mean_sp ** (1.0 / p - 1.0)) * (1.0 / N) * (scaled ** (p - 1.0))

    dSp_dLp = dq / (s * s * Mp) - q * dMp / (s * s * Mp * Mp)
    dSp_ds = -2.0 * q / (s ** 3 * Mp)

    g = dSp_dLp[1:-1]
    grad_h = 2.0 * np.correlate(g, h, 'valid')
    grad_h += dSp_ds
    return Sp, grad_h


def resample(h, n):
    if h.size == n:
        return h.copy()
    idx = np.linspace(0, h.size - 1, n)
    return np.interp(idx, np.arange(h.size), h)


def _lbfgs_full(h0, p, maxiter, deadline):
    n = h0.size

    def fg(h):
        if time.process_time() >= deadline:
            raise TimeoutError
        val, g = score_and_grad_p(h, p)
        return -val, -g

    try:
        res = minimize(fg, h0, jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * n,
                       options={'maxiter': maxiter, 'ftol': 1e-14, 'gtol': 1e-12})
        return np.clip(res.x, 0, None)
    except TimeoutError:
        return h0


def _golden_1d(fun, lo, hi, iters=40):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    a, b = lo, hi
    c = b - gr * (b - a)
    d = a + gr * (b - a)
    fc = fun(c); fd = fun(d)
    for _ in range(iters):
        if fc > fd:
            b, d, fd = d, c, fc
            c = b - gr * (b - a)
            fc = fun(c)
        else:
            a, c, fc = c, d, fd
            d = a + gr * (b - a)
            fd = fun(d)
    return 0.5 * (a + b)


def _coord_polish(h, deadline, rng, rounds=4):
    h = np.array(h, dtype=float)
    cur = score(h)
    n = h.size
    for _ in range(rounds):
        if time.process_time() >= deadline:
            break
        improved = False
        order = rng.permutation(n)
        for i in order:
            if time.process_time() >= deadline:
                break
            base = h[i]
            hi = max(3.0 * base, h.mean() * 3.0, 1e-6)

            def f(x, i=i):
                hx = h.copy(); hx[i] = x
                return score(hx)

            x = _golden_1d(f, 0.0, hi, iters=24)
            fx = f(x)
            if fx > cur + 1e-15:
                h[i] = x
                cur = fx
                improved = True
        if not improved:
            break
    return h, cur


def _window_polish(h, deadline, rng, sizes=(2, 3, 5, 9, 17, 33)):
    h = np.array(h, dtype=float)
    cur = score(h)
    n = h.size
    if n < 2:
        return h, cur
    for k in sizes:
        if k > n:
            continue
        starts = rng.permutation(n - k + 1)
        for i in starts:
            if time.process_time() >= deadline:
                return h, cur
            seg = h[i:i + k].copy()
            if seg.sum() <= 0:
                continue
            base_scale = 1.0

            def f_scale(x):
                hx = h.copy(); hx[i:i + k] = seg * x
                return score(hx)

            x = _golden_1d(f_scale, 0.0, 3.0, iters=18)
            fx = f_scale(x)
            if fx > cur + 1e-15:
                h[i:i + k] = seg * x
                cur = fx
                seg = h[i:i + k].copy()

            lin = np.linspace(-1.0, 1.0, k)

            def f_tilt(t):
                hx = h.copy()
                hx[i:i + k] = seg * np.clip(1.0 + t * lin, 0.0, None)
                return score(hx)

            t = _golden_1d(f_tilt, -0.8, 0.8, iters=18)
            ft = f_tilt(t)
            if ft > cur + 1e-15:
                h[i:i + k] = seg * np.clip(1.0 + t * lin, 0.0, None)
                cur = ft
    return h, cur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    best = base.copy()
    best_score = score(best)
    rng = np.random.default_rng(987654321)

    total = deadline - t0
    fin_deadline = t0 + total * 0.70
    pol_deadline = t0 + total * 0.90

    # --- Phase A: p-ladder L-BFGS-B descent on the start ---
    p_ladder = [256, 1024, 4096, 16384, 65536, None]
    h = best.copy()
    for p in p_ladder:
        if time.process_time() >= fin_deadline:
            break
        if p is None:
            # exact polish via coordinate sweeps
            h, cur = _coord_polish(h, fin_deadline, rng, rounds=3)
        else:
            h = _lbfgs_full(h, p, 400, fin_deadline)
        sc = score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()

    # --- Phase B: try upsampling to finer grids and refining ---
    for N in (best.size * 2, best.size * 3, 150, 200):
        if time.process_time() >= fin_deadline:
            break
        N = int(min(400, max(best.size, N)))
        if N <= best.size:
            continue
        h = resample(best, N)
        for p in (4096, 16384, 65536):
            if time.process_time() >= fin_deadline:
                break
            h = _lbfgs_full(h, p, 300, fin_deadline)
        h, cur = _coord_polish(h, fin_deadline, rng, rounds=2)
        sc = score(h)
        if sc > best_score:
            best_score = sc
            best = h.copy()

    # --- Phase C: window polish on true R (tilt/scale) ---
    h, cur = _window_polish(best, pol_deadline, rng)
    if cur > best_score:
        best_score = cur
        best = h.copy()

    # --- Phase D: final coordinate polish on true R ---
    h, cur = _coord_polish(best, deadline, rng, rounds=6)
    if cur > best_score:
        best_score = cur
        best = h.copy()

    # --- Phase E: random perturbations to escape local optima ---
    step = 0.15
    stall = 0
    while time.process_time() < deadline:
        cand = best.copy()
        n = cand.size
        k = int(rng.integers(1, max(2, n // 8 + 1)))
        i = int(rng.integers(0, max(1, n - k)))
        cand[i:i + k] *= np.exp(rng.normal(0, step, k))
        cand = np.clip(cand, 0, None)
        if cand.sum() <= 0:
            continue
        sc = score(cand)
        if sc > best_score:
            best_score = sc
            best = cand.copy()
            stall = 0
        else:
            stall += 1
        if stall > 200:
            step = max(0.02, step * 0.7)
            stall = 0
        if step < 0.02 and time.process_time() < deadline - 0.5:
            # local polish
            h, cur = _coord_polish(best, min(deadline, time.process_time() + 1.0),
                                   rng, rounds=2)
            if cur > best_score:
                best_score = cur
                best = h.copy()
            step = 0.15

    return best

