        def f(x):
            hx = h.copy(); hx[i] = base * x
            return score(hx)
        x = _golden_1d(f, 0.0, 3.0, iters=28)
        fx = f(x)
        if fx > cur + 1e-16:
            h[i] = base * x
            cur = fx
            improved = True

