    deadline = t0 + budget_seconds * 0.92
    rng = np.random.default_rng(20240607)

    if start is not None:
        base = np.asarray(start, dtype=float).copy()
        base = np.clip(base, 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    best = base.copy()
    best_score = score(best)

    win = (2, 3, 4, 5, 7, 9, 13, 17, 25, 33)

    # Stage 1: descent at start resolution
    tA = t0 + budget_seconds * 0.30
    h, c = _descent(best, tA, rng, win)
    if c > best_score:
        best, best_score = h.copy(), c

    # Stage 2: finer resolution
    tB = t0 + budget_seconds * 0.50
    if time.process_time() < tB and best.size < 1200:
        n2 = best.size * 2
        h2 = resample(best, n2)
        h2, c2 = _descent(h2, tB, rng, win)
        if c2 > best_score:
            best, best_score = h2.copy(), c2

    # Stage 3: smoothing + descent — exploit that optimum may be smoother
    tC = t0 + budget_seconds * 0.65
    if time.process_time() < tC:
        for alpha in (0.15, 0.3, 0.5):
            if time.process_time() >= tC:
                break
            hs = _smooth(best, alpha)
            hs = np.clip(hs, 0, None)
            hs, cs = _descent(hs, tC, rng, win)
            if cs > best_score:
                best, best_score = hs.copy(), cs

    # Stage 4: basin hopping
    while time.process_time() < deadline:
        cand = _perturb(best, rng)
        cand, cscore = _descent(cand, deadline, rng, (3, 5, 9, 17))
        if cscore > best_score:
            best, best_score = cand.copy(), cscore

    return best

import numpy as np
import time


def score(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    a = Lp[:-1]
    b = Lp[1:]
    q = np.sum(a * a + a * b + b * b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0
    return q / (s * s * m)


def _golden_1d(fun, lo, hi, iters=22):
    gr = (np.sqrt(5.0) - 1.0) / 2.0
    a, b = lo, hi
    c = b - gr * (b - a)
    d = a + gr * (b - a)
    fc = fun(c); fd = fun(d)
    for _ in range(iters):
        if fc > fd:
            b, d, fd = d, c, fc
            c = b - gr * (b - a)
            fc = fun(c)
        else:
            a, c, fc = c, d, fd
            d = a + gr * (b - a)
            fd = fun(d)
    return 0.5 * (a + b)


def _coord_sweep(h, deadline, rng, hi_mult=3.0):
    """Coordinate sweep: multiply each h[i] by golden-searched factor."""
    n = h.size
    cur = score(h)
    order = rng.permutation(n)
    improved = False
    for i in order:
        if time.process_time() >= deadline:
            break
        base = h[i]
        if base <= 0:
            lo, hi = 0.0, max(1e-3, h.mean() * hi_mult)
        else:
            lo, hi = 0.0, hi_mult

        def f(x, i=i, base=base):
            hh = h.copy()
            hh[i] = base * x
            return score(hh)

        x = _golden_1d(f, lo, hi, iters=28)
        fx = f(x)
        if fx > cur + 1e-16:
            h[i] = base * x
            cur = fx
            improved = True
    return h, cur, improved


def _window_sweep(h, deadline, rng, sizes=(2, 3, 5, 9, 17, 33)):
    """Window sweeps: scale and tilt contiguous windows."""
    n = h.size
    cur = score(h)
    improved = False
    for k in sizes:
        if k > n:
            continue
        starts = rng.permutation(n - k + 1)
        for i in starts:
            if time.process_time() >= deadline:
                return h, cur, improved
            seg = h[i:i + k].copy()
            if seg.sum() <= 0:
                continue

            def f_scale(x, i=i, seg=seg):
                hh = h.copy()
                hh[i:i + k] = seg * x
                return score(hh)

            x = _golden_1d(f_scale, 0.0, 3.0, iters=18)
            fx = f_scale(x)
            if fx > cur + 1e-16:
                h[i:i + k] = seg * x
                cur = fx
                improved = True
                seg = h[i:i + k].copy()

            lin = np.linspace(-1.0, 1.0, k)

            def f_tilt(t, i=i, seg=seg, lin=lin):
                hh = h.copy()
                hh[i:i + k] = np.clip(seg * (1.0 + t * lin), 0.0, None)
                return score(hh)

            t = _golden_1d(f_tilt, -0.8, 0.8, iters=16)
            ft = f_tilt(t)
            if ft > cur + 1e-16:
                h[i:i + k] = np.clip(seg * (1.0 + t * lin), 0.0, None)
                cur = ft
                improved = True
    return h, cur, improved


def _smooth_perturb(h, rng, scale):
    n = h.size
    x = np.arange(n, dtype=float)
    pert = np.zeros(n)
    for _ in range(3):
        c = rng.uniform(0, n)
        w = rng.uniform(n * 0.05, n * 0.30)
        amp = rng.uniform(-scale, scale)
        pert += amp * np.exp(-0.5 * ((x - c) / w) ** 2)
    return np.clip(h * (1.0 + pert), 0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    best = base.copy()
    best_score = score(best)
    rng = np.random.default_rng(1234567)

    # Phase 1: full coordinate sweeps + window sweeps until convergence.
    h = best.copy()
    cur = best_score
    while time.process_time() < deadline:
        h, cur, imp1 = _coord_sweep(h, deadline, rng)
        if cur > best_score:
            best_score = cur; best = h.copy()
        if time.process_time() >= deadline:
            break
        h, cur, imp2 = _window_sweep(h, deadline, rng)
        if cur > best_score:
            best_score = cur; best = h.copy()
        if not (imp1 or imp2):
            break

    # Phase 2: basin-hopping with smooth perturbations + short local polish.
    while time.process_time() < deadline:
        rem = deadline - time.process_time()
        if rem < 0.3:
            break
        cand = _smooth_perturb(best, rng, scale=rng.uniform(0.05, 0.20))
        cc = score(cand)
        sub_deadline = min(deadline, time.process_time() + rem * 0.6)
        for _ in range(3):
            if time.process_time() >= sub_deadline:
                break
            cand, cc, imp = _coord_sweep(cand, sub_deadline, rng)
            if not imp:
                break
        if cc > best_score:
            best_score = cc; best = cand.copy()

    # Phase 3: final coordinate + window polish on best.
    h = best.copy()
    cur = best_score
    while time.process_time() < deadline:
        h, cur, imp1 = _coord_sweep(h, deadline, rng)
        if cur > best_score:
            best_score = cur; best = h.copy()
        if time.process_time() >= deadline:
            break
        h, cur, imp2 = _window_sweep(h, deadline, rng, sizes=(2, 3, 5))
        if cur > best_score:
            best_score = cur; best = h.copy()
        if not (imp1 or imp2):
            break

    return best

import numpy as np
import time

def _knots(h):
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0
    Lp[-1] = 0.0
    Lp[1:-1] = L
    return Lp

def score(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    Lp = _knots(h)
    a = Lp[:-1]; b = Lp[1:]
    q = np.sum(a*a + a*b + b*b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0
    return q / (s*s*m)

def _score_and_grad(h):
    h = np.asarray(h, dtype=float)
    n = h.size
    s = h.sum()
    if s <= 0:
        return 0.0, np.zeros(n)
    L = np.convolve(h, h)
    Lp = np.empty(L.size + 2)
    Lp[0] = 0.0; Lp[-1] = 0.0; Lp[1:-1] = L
    a = Lp[:-1]; b = Lp[1:]
    q = np.sum(a*a + a*b + b*b) / 3.0
    m = Lp.max()
    if m <= 0:
        return 0.0, np.zeros(n)
    R = q / (s*s*m)

    dq = np.empty(Lp.size)
    dq[1:-1] = (2.0*Lp[1:-1] + Lp[2:])/3.0 + (Lp[:-2] + 2.0*Lp[1:-1])/3.0
    dq[0] = (2.0*Lp[0] + Lp[1])/3.0
    dq[-1] = (Lp[-2] + 2.0*Lp[-1])/3.0

    imax = int(np.argmax(Lp))
    term2 = np.convolve(dq, h)[:n]
    term1_full = np.convolve(dq, h[::-1])
    term1 = term1_full[n-1:n-1+n]
    dq_dh = term1 + term2

    dm_dh = np.zeros(n)
    k = imax
    lo = max(0, k-n+1); hi = min(n-1, k)
    for i in range(lo, hi+1):
        j = k - i
        if 0 <= j < n:
            dm_dh[i] += h[j]
    lo2 = max(0, k); hi2 = min(n-1, k+n-1)
    for i in range(lo2, hi2+1):
        j = i - k
        if 0 <= j < n:
            dm_dh[i] += h[j]

    inv = 1.0/(s*s*m)
    grad = dq_dh*inv - R*(2.0/s + dm_dh/m)
    return R, grad

def _grad_ascent(h0, deadline, max_iter=500):
    h = np.array(h0, dtype=float)
    if h.sum() <= 0:
        h = np.ones_like(h)
    h /= h.sum()
    R, g = _score_and_grad(h)
    best_h = h.copy(); best_R = R
    step = 1e-3
    it = 0
    while time.process_time() < deadline and it < max_iter:
        it += 1
        gn = np.linalg.norm(g)
        if gn < 1e-15:
            break
        trial = h + step*g/gn
        trial = np.clip(trial, 0.0, None)
        st = trial.sum()
        if st <= 0:
            step *= 0.5; continue
        trial /= st
        R2, g2 = _score_and_grad(trial)
        if R2 > R + 1e-17:
            h, R, g = trial, R2, g2
            if R > best_R:
                best_R = R; best_h = h.copy()
            step *= 1.3
        else:
            step *= 0.5
            if step < 1e-14:
                break
    return best_h, best_R

def _coord_polish(h, deadline, rng, hi_mult=2.0):
    h = np.array(h, dtype=float)
    cur = score(h)
    n = h.size
    gr = (np.sqrt(5.0)-1.0)/2.0
    improved = True
    while improved and time.process_time() < deadline:
        improved = False
        order = rng.permutation(n)
        for i in order:
            if time.process_time() >= deadline:
                return h, cur
            base = h[i]
            if base <= 0:
                lo, hi = 0.0, max(1e-4, h.mean()*hi_mult)
            else:
                lo, hi = 0.0, base*hi_mult
            a, b = lo, hi
            c = b - gr*(b-a); d = a + gr*(b-a)
            hc = h.copy(); hc[i] = c if base <= 0 else base*c
            hd = h.copy(); hd[i] = d if base <= 0 else base*d
            fc = score(hc); fd = score(hd)
            for _ in range(26):
                if fc > fd:
                    b, d, fd = d, c, fc
                    c = b - gr*(b-a)
                    hc = h.copy(); hc[i] = c if base <= 0 else base*c
                    fc = score(hc)
                else:
                    a, c, fc = c, d, fd
                    d = a + gr*(b-a)
                    hd = h.copy(); hd[i] = d if base <= 0 else base*d
                    fd = score(hd)
            x = 0.5*(a+b)
            hx = h.copy(); hx[i] = x if base <= 0 else base*x
            fx = score(hx)
            if fx > cur + 1e-17:
                h[i] = hx[i]; cur = fx; improved = True
    return h, cur

def _pair_polish(h, deadline, rng):
    h = np.array(h, dtype=float)
    cur = score(h)
    n = h.size
    if n < 2:
        return h, cur
    gr = (np.sqrt(5.0)-1.0)/2.0
    def golden(fun, lo, hi, iters=24):
        a, b = lo, hi
        c = b - gr*(b-a); d = a + gr*(b-a)
        fc = fun(c); fd = fun(d)
        for _ in range(iters):
            if fc > fd:
                b, d, fd = d, c, fc
                c = b - gr*(b-a); fc = fun(c)
            else:
                a, c, fc = c, d, fd
                d = a + gr*(b-a); fd = fun(d)
        return 0.5*(a+b)
    improved = True
    while improved and time.process_time() < deadline:
        improved = False
        order = rng.permutation(n-1)
        for i in order:
            if time.process_time() >= deadline:
                return h, cur
            seg = h[i:i+2].copy()
            if seg.sum() <= 0:
                continue
            def f_tilt(t):
                hx = h.copy()
                hx[i:i+2] = seg*np.clip(1.0 + t*np.array([-1.0,1.0]), 0.0, None)
                return score(hx)
            t = golden(f_tilt, -0.9, 0.9)
            ft = f_tilt(t)
            if ft > cur + 1e-17:
                h[i:i+2] = seg*np.clip(1.0 + t*np.array([-1.0,1.0]), 0.0, None)
                cur = ft; improved = True
    return h, cur

def _window_polish(h, deadline, rng, sizes):
    h = np.array(h, dtype=float)
    cur = score(h)
    n = h.size
    gr = (np.sqrt(5.0)-1.0)/2.0
    def golden(fun, lo, hi, iters=20):
        a, b = lo, hi
        c = b - gr*(b-a); d = a + gr*(b-a)
        fc = fun(c); fd = fun(d)
        for _ in range(iters):
            if fc > fd:
                b, d, fd = d, c, fc
                c = b - gr*(b-a); fc = fun(c)
            else:
                a, c, fc = c, d, fd
                d = a + gr*(b-a); fd = fun(d)
        return 0.5*(a+b)
    for w in sizes:
        if w > n:
            continue
        improved = True
        while improved and time.process_time() < deadline:
            improved = False
            starts = rng.permutation(max(1, n-w+1))
            for st in starts:
                if time.process_time() >= deadline:
                    return h, cur
                i0 = int(st); i1 = min(n, i0+w)
                seg = h[i0:i1].copy()
                if seg.sum() <= 0:
                    continue
                xs = np.linspace(-1.0, 1.0, i1-i0)
                def f_tilt(t):
                    hx = h.copy()
                    hx[i0:i1] = seg*np.clip(1.0 + t*xs, 0.0, None)
                    return score(hx)
                t = golden(f_tilt, -0.9, 0.9)
                ft = f_tilt(t)
                if ft > cur + 1e-17:
                    h[i0:i1] = seg*np.clip(1.0 + t*xs, 0.0, None)
                    cur = ft; improved = True
    return h, cur

def _fourier_candidates(N, M=8704):
    u = np.fft.fftfreq(M)
    cands = []
    for W in (0.6, 0.8, 1.0, 1.2, 1.5, 2.0):
        That = W*np.sinc(W*u)
        P = np.maximum(That, 0.0)
        Fhat = np.sqrt(P)
        f = np.real(np.fft.ifft(Fhat))
        f = np.roll(f, M//2)
        for variant in (f, np.maximum(f, 0.0), np.abs(f)):
            if M % N == 0:
                binned = variant.reshape(N, M//N).mean(axis=1)
            else:
                binned = np.array([variant[int(k*M/N):int((k+1)*M/N)].mean() for k in range(N)])
            binned = np.clip(binned, 0.0, None)
            s = binned.sum()
            if s <= 0:
                continue
            cands.append(binned/s)
    return cands

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.0
    rng = np.random.default_rng(12345)

    if start is not None and len(start) > 0:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.clip(h0, 0.0, None)
        if h0.sum() <= 0:
            h0 = np.ones(1)
    else:
        h0 = np.ones(136)

    N = h0.size
    best = h0.copy()
    best_score = score(best)

    # Multi-scale refinement: try increasing N by interpolating the current best.
    # This often escapes local optima fixed at a given discretization.
    def refine_to(h, newN):
        old = np.linspace(0, 1, h.size+1)
        new = np.linspace(0, 1, newN+1)
        out = np.zeros(newN)
        for k in range(newN):
            c = 0.5*(new[k]+new[k+1])
            out[k] = np.interp(c, 0.5*(old[:-1]+old[1:]), h)
        out = np.clip(out, 0.0, None)
        s = out.sum()
        return out/s if s > 0 else h

    # Try a few discretizations of the start.
    refinements = []
    for mult in (1, 2, 3, 4):
        newN = min(200000, N*mult)
        if newN == N:
            refinements.append(h0.copy())
        else:
            refinements.append(refine_to(h0, newN))

    # Score all and shortlist.
    scored = [(score(r), r) for r in refinements]
    scored.sort(key=lambda x: -x[0])
    # Keep top few, plus diverse sizes
    shortlist = []
    seen_sizes = set()
    for sc, r in scored:
        if len(shortlist) >= 3:
            break
        shortlist.append((sc, r))
    # Ensure at least one larger-N candidate even if slightly worse.
    if N < 200000:
        largeN = min(200000, N*4)
        if largeN != N:
            big = refine_to(h0, largeN)
            if all(big.size != r.size for _, r in shortlist):
                shortlist.append((score(big), big))

    # Per-candidate budget.
    n_cand = len(shortlist)
    per_cand = 0.55*budget_seconds/max(1, n_cand)

    for sc, r in shortlist:
        if time.process_time() >= deadline:
            break
        sub_deadline = min(deadline, time.process_time() + per_cand)
        h = r.copy()
        cur = sc
        # Gradient ascent first.
        if time.process_time() < sub_deadline:
            h2, s2 = _grad_ascent(h, min(sub_deadline, time.process_time() + 0.5*per_cand))
            if s2 > cur:
                h, cur = h2, s2
        # Coordinate polish.
        if time.process_time() < sub_deadline:
            h2, s2 = _coord_polish(h, sub_deadline, rng)
            if s2 > cur:
                h, cur = h2, s2
        # Pair polish.
        if time.process_time() < sub_deadline:
            h2, s2 = _pair_polish(h, sub_deadline, rng)
            if s2 > cur:
                h, cur = h2, s2
        # Window polish.
        if time.process_time() < sub_deadline:
            h2, s2 = _window_polish(h, sub_deadline, rng, (3, 5, 9, 17, 25, 33))
            if s2 > cur:
                h, cur = h2, s2
        if cur > best_score:
            best, best_score = h.copy(), cur

    # Final full polish of overall best until deadline.
    while time.process_time() < deadline:
        h2, s2 = _grad_ascent(best, min(deadline, time.process_time() + 2.0))
        if s2 > best_score:
            best, best_score = h2, s2
        if time.process_time() >= deadline:
            break
        h2, s2 = _coord_polish(best, min(deadline, time.process_time() + 2.0), rng)
        if s2 > best_score:
            best, best_score = h2, s2
        if time.process_time() >= deadline:
            break
        h2, s2 = _pair_polish(best, min(deadline, time.process_time() + 2.0), rng)
        if s2 > best_score:
            best, best_score = h2, s2
        if time.process_time() >= deadline:
            break
        h2, s2 = _window_polish(best, min(deadline, time.process_time() + 2.0), rng, (3,5,9,17,25,33))
        if s2 > best_score:
            best, best_score = h2, s2

    best = np.clip(best, 0.0, None)
    if best.sum() <= 0:
        best = np.ones(1)
    return best
